import { useState } from "react";
import { ColorPicker, Form, FormField } from "@godxjp/ui/data-entry";

export function BrandColorField() {
  const [color, setColor] = useState("#2563eb");

  return (
    <Form>
      <FormField id="brand-color" label="Brand color">
        <ColorPicker id="brand-color" value={color} onValueChange={setColor} />
      </FormField>
    </Form>
  );
}

// Compact swatch-only variant (no hex input)
export function SwatchOnly() {
  const [color, setColor] = useState("#16a34a");
  return <ColorPicker value={color} onValueChange={setColor} showHexInput={false} />;
}

// Fixed palette only (gh#1055): tags pick from presets, never free hex
export function TagColorField() {
  const [color, setColor] = useState("#2563eb");
  return (
    <Form>
      <FormField id="tag-color" label="Tag colour">
        <ColorPicker
          id="tag-color"
          value={color}
          onValueChange={setColor}
          presets={[{ label: "Palette", colors: ["#dc2626", "#16a34a", "#2563eb", "#9333ea"] }]}
          panelRender={(_, { components: { Presets } }) => <Presets />}
        />
      </FormField>
    </Form>
  );
}

// Disabled state
export function DisabledColor() {
  return <ColorPicker value="#6b7280" disabled />;
}
